import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { getRoomsForOwner, deleteRoom, updateRoomStatus, getBookingsForOwner } from '../api/listingService';
import { toast } from "sonner";
import {
    Card,
    CardContent,
    CardHeader,
    CardTitle
} from "../components/ui/card";
import { Button } from "../components/ui/button";
import { Input } from "../components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "../components/ui/select";
import { Badge } from "../components/ui/badge";
import { Search, Home, Settings, Trash2, Eye, Edit3, Wrench, MapPin, IndianRupee, Plus, Users, Unlock, Check, Building } from 'lucide-react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "../components/ui/dialog";
import Pagination from '../components/ui/Pagination';

// Icons for room types
const RoomIcon = ({ type }) => {
    switch (type) {
        case 'single':
            return <Home className="h-8 w-8 text-gray-600" />;
        case 'double':
            return <Building className="h-8 w-8 text-gray-600" />;
        case 'shared':
            return <Settings className="h-8 w-8 text-gray-600" />;
        case 'maintenance':
            return <Wrench className="h-8 w-8 text-gray-600" />;
        case 'occupied':
            return <Building className="h-8 w-8 text-green-600" />;
        default:
            return <Home className="h-8 w-8 text-gray-600" />;
    }
};

// Helper to get display status
const getDisplayStatus = (room) => {
    if (room.isOccupied) return 'occupied';
    if (room.status === 'maintenance') return 'maintenance';
    return 'available';
};

const OwnerRoomsPage = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const [rooms, setRooms] = useState([]);
    const [loading, setLoading] = useState(true);

    const serviceType = user?.serviceType;
    const canCreateRoom = serviceType === 'room' || serviceType === 'both';
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');
    const [sortOrder, setSortOrder] = useState('newest');
    const [currentPage, setCurrentPage] = useState(1);
    const itemsPerPage = 8;

    // Dialog states
    const [deleteDialog, setDeleteDialog] = useState({ open: false, roomId: null });
    const [deactivateDialog, setDeactivateDialog] = useState({ open: false, roomId: null });

    useEffect(() => {
        const fetchData = async () => {
            try {
                const [roomsData, bookingsData] = await Promise.all([
                    getRoomsForOwner(),
                    getBookingsForOwner()
                ]);

                // Find room IDs that have confirmed bookings
                const occupiedRoomIds = new Set(
                    bookingsData
                        .filter(b => b.status === 'confirmed' && b.item_type === 'room')
                        .map(b => b.item_id)
                );

                // Update rooms with dynamic occupancy status
                const roomsWithStatus = roomsData.map(room => ({
                    ...room,
                    isOccupied: occupiedRoomIds.has(room.room_id)
                }));

                setRooms(roomsWithStatus);
            } catch (error) {
                console.error("Failed to fetch rooms", error);
                toast.error("Failed to load rooms. Please refresh the page.");
                setRooms([]);
            } finally {
                setLoading(false);
            }
        };

        if (user) {
            fetchData();
        }
    }, [user]);

    // Handlers
    const handleDeleteRoom = (roomId) => {
        setDeleteDialog({ open: true, roomId });
    };

    const handleReactivateRoom = async (roomId) => {
        try {
            await updateRoomStatus(roomId, 'available');
            toast.success("Room reactivated!");
            setRooms(prev => prev.map(room =>
                room.room_id === roomId ? { ...room, status: 'available' } : room
            ));
        } catch (error) {
            toast.error(error.message || "Failed to reactivate room");
        }
    };

    const filteredRooms = rooms.filter(room => {
        const matchesSearch = room.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
            room.address.toLowerCase().includes(searchTerm.toLowerCase());
        const displayStatus = getDisplayStatus(room);
        const matchesStatus = statusFilter === 'all' || displayStatus === statusFilter;
        return matchesSearch && matchesStatus;
    });

    const getRentValue = (rent) => {
        if (!rent) return 0;
        const parsed = parseFloat(String(rent).replace(/[^0-9.-]+/g, ""));
        return isNaN(parsed) ? 0 : parsed;
    };

    const sortedRooms = [...filteredRooms].sort((a, b) => {
        if (sortOrder === 'newest') {
            return new Date(b.created_at) - new Date(a.created_at);
        } else if (sortOrder === 'oldest') {
            return new Date(a.created_at) - new Date(b.created_at);
        } else if (sortOrder === 'price-high') {
            return getRentValue(b.rent) - getRentValue(a.rent);
        } else if (sortOrder === 'price-low') {
            return getRentValue(a.rent) - getRentValue(b.rent);
        }
        return 0;
    });

    const paginatedRooms = useMemo(() => {
        const startIndex = (currentPage - 1) * itemsPerPage;
        return sortedRooms.slice(startIndex, startIndex + itemsPerPage);
    }, [sortedRooms, currentPage]);

    const handlePageChange = (page) => {
        setCurrentPage(page);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-gray-50 p-4 sm:p-6">
                <div className="max-w-7xl mx-auto">
                    <div className="flex justify-between items-center mb-6">
                        <div className="h-8 w-40 bg-gray-200 rounded animate-pulse"></div>
                        <div className="h-10 w-36 bg-gray-200 rounded animate-pulse"></div>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
                        {[1, 2, 3].map(i => (
                            <div key={i} className="bg-white rounded-xl p-6 border border-gray-200">
                                <div className="h-6 w-32 bg-gray-200 rounded mb-2 animate-pulse"></div>
                                <div className="h-10 w-24 bg-gray-200 rounded animate-pulse"></div>
                            </div>
                        ))}
                    </div>
                    <div className="bg-white p-4 rounded-xl shadow-sm mb-6">
                        <div className="h-10 w-full bg-gray-200 rounded animate-pulse"></div>
                    </div>
                    <div className="space-y-4">
                        {[1, 2, 3, 4].map(i => (
                            <div key={i} className="bg-white rounded-xl p-4 border border-gray-200 flex items-center animate-pulse">
                                <div className="w-20 h-20 bg-gray-200 rounded-lg mr-4"></div>
                                <div className="flex-grow">
                                    <div className="h-5 w-48 bg-gray-200 rounded mb-2"></div>
                                    <div className="h-4 w-64 bg-gray-200 rounded mb-2"></div>
                                    <div className="h-5 w-24 bg-gray-200 rounded"></div>
                                </div>
                                <div className="h-8 w-20 bg-gray-200 rounded"></div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 p-4 sm:p-6">
            <div className="max-w-7xl mx-auto">
{/* Header */}
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-800">Manage Rooms</h1>
        {canCreateRoom && (
          <Button
            onClick={() => navigate("/dashboard/create-room")}
            className="bg-green-600 hover:bg-green-700"
          >
            <Plus className="mr-2 h-5 w-5" />
            Add New Room
          </Button>
        )}
      </div>
      {!canCreateRoom && serviceType === 'mess' && (
        <div className="bg-amber-50 border border-amber-200 rounded-lg p-4 mb-6 text-center">
          <p className="text-amber-800">You are registered as a Mess provider. Room creation is not available for your account.</p>
        </div>
      )}
      {!serviceType && (
        <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6 text-center">
          <p className="text-blue-800">Please complete your profile to select your service type and start listing rooms.</p>
        </div>
      )}

                {/* Stats Cards */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
                    <Card>
                        <CardHeader>
                            <CardTitle>Total Rooms</CardTitle>
                        </CardHeader>
                        <CardContent>
                            <div className="flex items-center gap-3">
                                <div className="p-3 bg-green-50 rounded-lg">
                                    <Home className="text-green-600 h-6 w-6" />
                                </div>
                                <div>
                                    <div className="text-3xl font-bold">{rooms.length}</div>
                                    <div className="text-sm text-gray-500">Across {new Set(rooms.map(r => r.building)).size} buildings</div>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                    <Card>
                        <CardHeader>
                            <CardTitle>Available Rooms</CardTitle>
                        </CardHeader>
                        <CardContent>
                            <div className="flex items-center gap-3">
                                <div className="p-3 bg-green-50 rounded-lg">
                                    <Unlock className="text-green-600 h-6 w-6" />
                                </div>
                                <div>
                                    <div className="text-3xl font-bold text-green-600">
                                        {rooms.filter(r => getDisplayStatus(r) === 'available').length}
                                    </div>
                                    <div className="text-sm text-green-600">Ready for tenants</div>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                    <Card>
                        <CardHeader>
                            <CardTitle>Occupied Rooms</CardTitle>
                        </CardHeader>
                        <CardContent>
                            <div className="flex items-center gap-3">
                                <div className="p-3 bg-blue-50 rounded-lg">
                                    <Users className="text-blue-600 h-6 w-6" />
                                </div>
                                <div>
                                    <div className="text-3xl font-bold text-blue-600">
                                        {rooms.filter(r => getDisplayStatus(r) === 'occupied').length}
                                    </div>
                                    <div className="text-sm text-blue-600">Booked by students</div>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                </div>

                {/* Search & Filters */}
                <div className="bg-white p-4 rounded-xl shadow-sm mb-6">
                    <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                        <div className="relative flex-grow">
                            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-5 w-5" />
                            <Input
                                placeholder="Search your rooms by name, number, or location..."
                                value={searchTerm}
                                onChange={(e) => { setSearchTerm(e.target.value); setCurrentPage(1); }}
                                className="pl-10"
                            />
                        </div>
                        <Select value={statusFilter} onValueChange={(value) => { setStatusFilter(value); setCurrentPage(1); }}>
                            <SelectTrigger className="w-[180px]">
                                <SelectValue placeholder="All Statuses" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">All Statuses</SelectItem>
                                <SelectItem value="available">Available</SelectItem>
                                <SelectItem value="occupied">Occupied</SelectItem>
                                <SelectItem value="maintenance">Maintenance</SelectItem>
                            </SelectContent>
                        </Select>
                        <Select value={sortOrder} onValueChange={(value) => { setSortOrder(value); setCurrentPage(1); }}>
                            <SelectTrigger className="w-[200px]">
                                <SelectValue placeholder="Sort by: Newest" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="newest">Sort by: Newest</SelectItem>
                                <SelectItem value="oldest">Sort by: Oldest</SelectItem>
                                <SelectItem value="price-high">Price: High to Low</SelectItem>
                                <SelectItem value="price-low">Price: Low to High</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>
                </div>

                {/* Rooms List */}
                <div className="space-y-4">
                    {paginatedRooms.length > 0 ? (
                        paginatedRooms.map(room => {
                            const displayStatus = getDisplayStatus(room);
                            return (
                                <Card key={room.room_id} className="hover:shadow-md transition-shadow">
                                    <div className="flex items-center p-4">
                                        <div className={`w-20 h-20 ${displayStatus === 'available' ? 'bg-green-50' : displayStatus === 'occupied' ? 'bg-blue-50' : 'bg-yellow-50'} flex items-center justify-center rounded-lg mr-4`}>
                                            <RoomIcon type={displayStatus} />
                                        </div>
                                        <div className="flex-grow">
                                            <div className="flex items-center gap-2">
                                                <h3
                                                    className="text-xl font-bold text-gray-800 hover:text-green-600 cursor-pointer transition-colors"
                                                    onClick={() => navigate(`/rooms/${room.room_id}`)}
                                                >
                                                    {room.title}
                                                </h3>
                                                <Badge variant="outline" className={`text-xs ${displayStatus === 'available' ? 'text-green-600 border-green-200' : displayStatus === 'occupied' ? 'text-blue-600 border-blue-200' : 'text-yellow-600 border-yellow-200'}`}>
                                                    {displayStatus === 'available' ? 'Available' : displayStatus === 'occupied' ? 'Occupied' : 'Maintenance'}
                                                </Badge>
                                            </div>
                                            <div className="flex items-center gap-2 mt-1 text-gray-500">
                                                <MapPin className="h-4 w-4" />
                                                <span className="line-clamp-1">{room.address}</span>
                                            </div>
                                            <div className="flex items-center gap-2 mt-2">
                                                {room.roomType && <Badge variant="secondary">{room.roomType}</Badge>}
                                                {room.ac && <Badge variant="secondary">AC</Badge>}
                                                {room.bathroom && <Badge variant="secondary">Attached Bath</Badge>}
                                            </div>
                                        </div>
                                        <div className="text-right min-w-[100px]">
                                            <div className="text-2xl font-bold text-green-600 flex items-center justify-end">
                                                <IndianRupee className="h-5 w-5 mr-1" />
                                                {room.rent}/mo
                                            </div>
                                            <div className="text-xs text-gray-500">Last updated: {new Date(room.updated_at).toLocaleDateString()}</div>
                                        </div>
                                        <div className="ml-4 flex gap-2">
                                            <Button variant="outline" size="sm" onClick={() => navigate(`/rooms/${room.room_id}`)}>
                                                <Eye className="mr-1 h-4 w-4" />
                                                View Details
                                            </Button>
                                            <Button variant="outline" size="sm" onClick={() => navigate(`/dashboard/create-room?edit=${room.room_id}`)}>
                                                <Edit3 className="mr-1 h-4 w-4" />
                                                Edit
                                            </Button>
                                            {displayStatus === 'available' ? (
                                                <Button variant="destructive" size="sm" onClick={() => handleDeleteRoom(room.room_id)}>
                                                    <Trash2 className="mr-1 h-4 w-4" />
                                                    Delete
                                                </Button>
                                            ) : displayStatus === 'occupied' ? (
                                                <Button variant="outline" size="sm" disabled>
                                                    <Users className="mr-1 h-4 w-4" />
                                                    Occupied
                                                </Button>
                                            ) : (
                                                <Button variant="outline" size="sm" className="text-green-600 border-green-200 hover:bg-green-50" onClick={() => handleReactivateRoom(room.room_id)}>
                                                    <Check className="mr-1 h-4 w-4" />
                                                    Reactivate
                                                </Button>
                                            )}
                                        </div>
                                    </div>
                                </Card>
                            );
                        })
) : (
        <Card className="text-center py-12">
          <div className="mb-4">
            <Building className="mx-auto h-12 w-12 text-gray-400" />
          </div>
          <h3 className="text-xl font-semibold text-gray-800 mb-2">No Rooms Found</h3>
          <p className="text-gray-500 mb-4">You haven't added any rooms yet.</p>
          {canCreateRoom && (
            <Button onClick={() => navigate("/dashboard/create-room")} className="bg-green-600 hover:bg-green-700">
              <Plus className="mr-2 h-5 w-5" />
              Add Your First Room
            </Button>
          )}
        </Card>
      )}
                </div>

                {/* Pagination */}
                <Pagination
                    currentPage={currentPage}
                    totalItems={sortedRooms.length}
                    itemsPerPage={itemsPerPage}
                    onPageChange={handlePageChange}
                />
            </div>

            {/* Delete Confirmation Dialog */}
            <Dialog open={deleteDialog.open} onOpenChange={() => setDeleteDialog({ open: false, roomId: null })}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>Delete Room</DialogTitle>
                        <DialogDescription>
                            Are you sure you want to delete this room? This action cannot be undone.
                        </DialogDescription>
                    </DialogHeader>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setDeleteDialog({ open: false, roomId: null })}>
                            Cancel
                        </Button>
                        <Button
                            variant="destructive"
                            onClick={async () => {
                                try {
                                    await deleteRoom(deleteDialog.roomId);
                                    toast.success("Room deleted successfully!");
                                    setRooms(prev => prev.filter(room => room.room_id !== deleteDialog.roomId));
                                } catch (error) {
                                    toast.error(error.message || "Failed to delete room");
                                } finally {
                                    setDeleteDialog({ open: false, roomId: null });
                                }
                            }}
                        >
                            Delete Room
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Deactivate Confirmation Dialog */}
            <Dialog open={deactivateDialog.open} onOpenChange={() => setDeactivateDialog({ open: false, roomId: null })}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>Deactivate Room</DialogTitle>
                        <DialogDescription>
                            Deactivate this room? It will no longer be available for booking.
                        </DialogDescription>
                    </DialogHeader>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setDeactivateDialog({ open: false, roomId: null })}>
                            Cancel
                        </Button>
                        <Button
                            variant="destructive"
                            onClick={async () => {
                                try {
                                    await updateRoomStatus(deactivateDialog.roomId, 'maintenance');
                                    toast.success("Room deactivated!");
                                    setRooms(prev => prev.map(room =>
                                        room.room_id === deactivateDialog.roomId ? { ...room, status: 'maintenance' } : room
                                    ));
                                } catch (error) {
                                    toast.error(error.message || "Failed to deactivate room");
                                } finally {
                                    setDeactivateDialog({ open: false, roomId: null });
                                }
                            }}
                        >
                            Deactivate
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
};

export default OwnerRoomsPage;